//go:build !purego

package h264enc

//go:generate go run neon_gen.go

// NEON kernels (neon_arm64.s, generated by neon_gen.go with macOS clang;
// the generated file is committed). They do no bounds checks: the
// wrappers in quant.go check the whole access first.

const haveNEON = true

//go:noescape
func neonSAD(a *byte, as int, b *byte, bs int, w, h int, out *int)

//go:noescape
func neonSATD(a *byte, as int, b *byte, bs int, w, h int, out *int)

//go:noescape
func neonDCTQuant8(src *byte, ss int, pred *byte, ps int, mf *[4][8]uint16, bias, qbits int, out *[64]int32, mask *int)
